return [{ json: { subject, html, _type: type } }];

const ctx = $('♻️ Restore Context').first().json;
const v = $json || {};
const reason = v.reason || 'No useful Ahrefs/SEMrush keyword (volume/KD/relevance) found for this topic';
return [{ json: { ...ctx, status: 'KEYWORD_FAILED', keyword_status: 'Skipped', skip_reason: reason, last_error: 'Topic skipped: ' + reason, phase_status: 'KEYWORD_SKIPPED' } }];

